import{c as a,Q as s,j as t,m as i}from"./chunks/framework.DoOjWOm2.js";const g=JSON.parse('{"title":"TV Shows Library Setup","description":"","frontmatter":{},"headers":[],"relativePath":"libraries/tv-shows.md","filePath":"libraries/tv-shows.md"}'),o={name:"libraries/tv-shows.md"};function n(d,e,l,r,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="tv-shows-library-setup" tabindex="-1">TV Shows Library Setup <a class="header-anchor" href="#tv-shows-library-setup" aria-label="Permalink to &quot;TV Shows Library Setup&quot;">​</a></h1><p><strong>Step:</strong> N.8 <strong>Since:</strong> 0.14.0</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>A TV library organizes your episodic content by show, season, and episode — with chapter markers, resume positions, and episode artwork all tracked per-user. Drop episodes into a <code>Season 01/</code> folder structure, add the folder to Phlix, and Phlix matches episode info from TVDB, Fanart.tv, and TMDB.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Structure: /TV/Show Name/Season 01/Show Name S01E01.ext</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add to Phlix: Libraries → Add Library → Type: TV Shows → point to /path/to/TV → Scan</span></span></code></pre></div><p>Supported formats: <code>.mkv</code>, <code>.mp4</code>, <code>.ts</code>, and most common video containers.</p><h2 id="_1-folder-and-file-naming-conventions" tabindex="-1">1. Folder and File Naming Conventions <a class="header-anchor" href="#_1-folder-and-file-naming-conventions" aria-label="Permalink to &quot;1. Folder and File Naming Conventions&quot;">​</a></h2><h3 id="_1a-standard-season-episode-format-recommended" tabindex="-1">1a. Standard Season/Episode Format (Recommended) <a class="header-anchor" href="#_1a-standard-season-episode-format-recommended" aria-label="Permalink to &quot;1a. Standard Season/Episode Format (Recommended)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/TV/Show Name/Season 01/Show Name S01E01.episode-title.ext</span></span>
<span class="line"><span>/TV/Show Name/Season 02/Show Name S02E03.ext</span></span></code></pre></div><ul><li><code>Season 01/</code> — <strong>zero-padded two-digit</strong> season number is required (not <code>Season 1/</code>)</li><li>Filename includes <code>S01E01</code> — zero-padded season and episode numbers</li><li><code>.</code> or <code>-</code> separator between show name and episode code is accepted</li><li>Episode title after the code is parsed and displayed in the UI</li></ul><h3 id="_1b-compact-flat-file-format" tabindex="-1">1b. Compact Flat-File Format <a class="header-anchor" href="#_1b-compact-flat-file-format" aria-label="Permalink to &quot;1b. Compact Flat-File Format&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/TV/Show Name/S01E01.ext</span></span>
<span class="line"><span>/TV/Show Name/S01E02.ext</span></span></code></pre></div><ul><li>No season folder; all episodes of a show in the same directory</li><li>Scanner detects show boundaries by shared show name prefix</li></ul><h3 id="_1c-absolute-episode-numbering" tabindex="-1">1c. Absolute Episode Numbering <a class="header-anchor" href="#_1c-absolute-episode-numbering" aria-label="Permalink to &quot;1c. Absolute Episode Numbering&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/TV/Show Name/1x01.ext</span></span>
<span class="line"><span>/TV/Show Name/1x02.ext</span></span></code></pre></div><ul><li>Used by some anime and older series that use consecutive numbering instead of season/episode</li><li><code>1x01</code> means episode 1 of season 1</li><li>Also supported: <code>Episode 001.ext</code></li></ul><h3 id="_1d-air-date-naming" tabindex="-1">1d. Air-Date Naming <a class="header-anchor" href="#_1d-air-date-naming" aria-label="Permalink to &quot;1d. Air-Date Naming&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/TV/Show Name/Show Name - 2012-03-02.ext</span></span>
<span class="line"><span>/TV/Show Name/Show Name - 2012-03-09.ext</span></span></code></pre></div><ul><li>Episode identified by original broadcast date — <code>YYYY-MM-DD</code> suffix</li><li>Scanner matches the air date against TVDB records to pull episode title and description</li></ul><h3 id="_1e-multi-version-episodes" tabindex="-1">1e. Multi-Version Episodes <a class="header-anchor" href="#_1e-multi-version-episodes" aria-label="Permalink to &quot;1e. Multi-Version Episodes&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/TV/Show Name (2020)/S01E01 - directors-cut.ext</span></span>
<span class="line"><span>/TV/Show Name (2020)/S01E01 - unrated.ext</span></span>
<span class="line"><span>/TV/Show Name (2020)/S01E01 - 4k-restored.ext</span></span></code></pre></div><ul><li>Parentheses disambiguate shows with the same name from different production years</li><li>Version tag after the episode code creates a separate library entry per version</li><li>Each version maintains its own playback state and resume position</li></ul><h2 id="_2-specials-and-bonus-episodes" tabindex="-1">2. Specials and Bonus Episodes <a class="header-anchor" href="#_2-specials-and-bonus-episodes" aria-label="Permalink to &quot;2. Specials and Bonus Episodes&quot;">​</a></h2><h3 id="season-00" tabindex="-1">Season 00 <a class="header-anchor" href="#season-00" aria-label="Permalink to &quot;Season 00&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/TV/Show Name/Season 00/Show Name S00E01.pilot.ext</span></span>
<span class="line"><span>/TV/Show Name/Season 00/Show Name S00E02.behind-the-scenes.ext</span></span></code></pre></div><ul><li>Special episodes belong in <code>Season 00/</code> (preferred) or <code>Specials/</code></li><li>Listed in the Specials season in the UI</li></ul><h3 id="specials-folder-alias" tabindex="-1">Specials Folder Alias <a class="header-anchor" href="#specials-folder-alias" aria-label="Permalink to &quot;Specials Folder Alias&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/TV/Show Name/Specials/S00E01.ext</span></span></code></pre></div><ul><li><code>Specials/</code> is accepted as an alias for <code>Season 00/</code> — both are merged into the same specials grouping in the UI</li></ul><h2 id="_3-episode-title-parsing-from-filename" tabindex="-1">3. Episode Title Parsing from Filename <a class="header-anchor" href="#_3-episode-title-parsing-from-filename" aria-label="Permalink to &quot;3. Episode Title Parsing from Filename&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Filename</th><th>Extracted Title</th></tr></thead><tbody><tr><td><code>Show Name S01E01.ext</code></td><td>(none — uses metadata)</td></tr><tr><td><code>Show Name S01E01.Pilot.ext</code></td><td>&quot;Pilot&quot;</td></tr><tr><td><code>Show Name S01E01 - The Pilot.ext</code></td><td>&quot;The Pilot&quot;</td></tr><tr><td><code>Show Name - 2012-03-02.ext</code></td><td>(none — uses air-date metadata)</td></tr></tbody></table><ul><li>Separator between episode code and title: <code>.</code>, <code>-</code>, or space</li><li>Title is shown in the episode list in the UI</li></ul><h2 id="_4-metadata-sources-and-priority" tabindex="-1">4. Metadata Sources and Priority <a class="header-anchor" href="#_4-metadata-sources-and-priority" aria-label="Permalink to &quot;4. Metadata Sources and Priority&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priority</th><th>Source</th><th>Notes</th></tr></thead><tbody><tr><td>1 (highest)</td><td>Local NFO</td><td><code>show.nfo</code> at show root, <code>episode.nfo</code> alongside video</td></tr><tr><td>2</td><td>TVDB</td><td>Primary TV metadata; strong episode-level data</td></tr><tr><td>3</td><td>Fanart.tv</td><td>Show logos, clearart, background images (UI chrome)</td></tr><tr><td>4</td><td>TMDB</td><td>Fallback; limited episode data but strong show-level</td></tr><tr><td>5 (lowest)</td><td>Filename parsing</td><td>Season/episode numbers and title as last resort</td></tr></tbody></table><p>All remote metadata is cached for 24 hours. Click <strong>Refresh Metadata</strong> on any item to force an immediate re-fetch.</p><h3 id="nfo-file-formats" tabindex="-1">NFO File Formats <a class="header-anchor" href="#nfo-file-formats" aria-label="Permalink to &quot;NFO File Formats&quot;">​</a></h3><p>Show-level (<code>show.nfo</code> at show root):</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tvshow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Show Name&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">year</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2020&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">year</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tvdbid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;81249&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tvdbid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tmdbid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;123456&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tmdbid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tvshow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Episode-level (<code>episode.nfo</code> alongside the video file):</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">episodedetails</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Episode Title&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">season</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">season</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">episode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">episode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">aired</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2020-01-15&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">aired</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Episode plot text.&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">episodedetails</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li><code>tvdbid</code> is the primary remote lookup key</li><li><code>tmdbid</code> is used as fallback when TVDB ID is not available</li></ul><h2 id="_5-scanner-behavior" tabindex="-1">5. Scanner Behavior <a class="header-anchor" href="#_5-scanner-behavior" aria-label="Permalink to &quot;5. Scanner Behavior&quot;">​</a></h2><h3 id="show-vs-movie-detection" tabindex="-1">Show vs. Movie Detection <a class="header-anchor" href="#show-vs-movie-detection" aria-label="Permalink to &quot;Show vs. Movie Detection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pattern in Filename</th><th>Classification</th><th>Example</th></tr></thead><tbody><tr><td><code>S01E01</code>, <code>1x01</code> in filename</td><td>TV episode</td><td><code>Show Name S01E01.mkv</code></td></tr><tr><td><code>(Year)</code> only, no episode code</td><td>Movie</td><td><code>Avatar (2009).mkv</code></td></tr><tr><td><code>Season 00/</code> or <code>Specials/</code> folder</td><td>TV (specials)</td><td><code>Season 00/</code></td></tr><tr><td><code>/TV/Show Name/</code> flat directory</td><td>TV show</td><td>All files in show folder</td></tr><tr><td>Both episode code AND year</td><td>TV (episode number wins)</td><td><code>Show (2020) S01E01.mkv</code></td></tr></tbody></table><p>Files matching the wrong library type are logged and skipped with a warning in the scan log.</p><h3 id="scan-triggering" tabindex="-1">Scan Triggering <a class="header-anchor" href="#scan-triggering" aria-label="Permalink to &quot;Scan Triggering&quot;">​</a></h3><ul><li><strong>Manual</strong>: Click <strong>Scan Library</strong> in the library&#39;s UI settings</li><li><strong>Automatic</strong>: Folder watcher detects <code>mtime</code> changes and queues an incremental rescan</li><li><strong>First add</strong>: Full recursive scan of the library root</li></ul><h3 id="incremental-rescans" tabindex="-1">Incremental Rescans <a class="header-anchor" href="#incremental-rescans" aria-label="Permalink to &quot;Incremental Rescans&quot;">​</a></h3><p>mtime-based checksum — only files whose modification time changed since the last scan are reprocessed. Show-level metadata (poster, fanart) is re-fetched only when <code>metadata_refreshed_at</code> is older than 24 hours.</p><h2 id="_6-content-rating-and-parental-controls" tabindex="-1">6. Content Rating and Parental Controls <a class="header-anchor" href="#_6-content-rating-and-parental-controls" aria-label="Permalink to &quot;6. Content Rating and Parental Controls&quot;">​</a></h2><p>Each user profile has a rating filter set in <strong>Settings → Profiles</strong>: G / PG / PG-13 / R / NC-17 / X / UNRATED. TV shows rated above the profile&#39;s filter are hidden from that profile&#39;s library view. TV ratings from TVDB are mapped to the MPAA equivalent scale.</p><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="incorrect-season-folder-naming" tabindex="-1">Incorrect Season Folder Naming <a class="header-anchor" href="#incorrect-season-folder-naming" aria-label="Permalink to &quot;Incorrect Season Folder Naming&quot;">​</a></h3><p><strong>Symptom:</strong> Episodes show under a separate show entry, or are not grouped at all.</p><p><strong>Cause:</strong> Using <code>Season 1/</code> instead of <code>Season 01/</code> — the scanner requires zero-padded two-digit season numbers.</p><p><strong>Fix:</strong> Rename all season folders to <code>Season 01</code>, <code>Season 02</code>, etc. (zero-padded two digits). Note: <code>Season 00</code> is correct for specials — not <code>Season 0</code> or <code>Specials/Season 00/</code>.</p><hr><h3 id="episode-number-conflicts" tabindex="-1">Episode Number Conflicts <a class="header-anchor" href="#episode-number-conflicts" aria-label="Permalink to &quot;Episode Number Conflicts&quot;">​</a></h3><p><strong>Symptom:</strong> Clicking one episode plays a different episode; the episode list shows wrong titles or duplicates.</p><p><strong>Cause:</strong> Two episodes with the same <code>S01E01</code> code in the same show directory from a multi-version setup where version tags are missing.</p><p><strong>Fix:</strong> Add a version tag to distinguish files: <code>Show Name S01E01 - directors-cut.mkv</code> vs. <code>Show Name S01E01.mkv</code>. Verify each <code>SxxExx</code> code is unique per show.</p><hr><h3 id="metadata-not-matching-tvdb-vs-tmdb-id-mismatch" tabindex="-1">Metadata Not Matching (TVDB vs. TMDB ID Mismatch) <a class="header-anchor" href="#metadata-not-matching-tvdb-vs-tmdb-id-mismatch" aria-label="Permalink to &quot;Metadata Not Matching (TVDB vs. TMDB ID Mismatch)&quot;">​</a></h3><p><strong>Symptom:</strong> Wrong show information appears, or no metadata is found despite correct episode numbers.</p><p><strong>Cause:</strong> TVDB and TMDB use different IDs for some shows; country-specific variants (e.g., &quot;The Office&quot; UK vs. US) can cross-match incorrectly.</p><p><strong>Fix:</strong> Create a <code>show.nfo</code> in the show root with the correct <code>tvdbid</code> (or <code>tmdbid</code> as fallback) to lock metadata to the correct provider record. Re-scan to apply.</p><hr><h3 id="duplicate-shows-from-different-paths" tabindex="-1">Duplicate Shows from Different Paths <a class="header-anchor" href="#duplicate-shows-from-different-paths" aria-label="Permalink to &quot;Duplicate Shows from Different Paths&quot;">​</a></h3><p><strong>Symptom:</strong> The same show appears twice (or more) in the library, each with a partial episode list.</p><p><strong>Cause:</strong> The same show root folder was added via two different library paths (e.g., symlinks or copies).</p><p><strong>Fix:</strong> Use a single library path per show. Run <strong>Empty Library</strong> then re-scan with a single path per show.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./movies.html">Movies library setup</a> — film organization, NFO metadata, extras handling</li><li><a href="./music.html">Music library setup</a> — album art, FLAC/MP3 tagging, compiled albums</li><li><a href="./../users/dlna.html">DLNA / Play To</a> — stream TV episodes to DLNA-compatible TVs and speakers</li></ul>`,73)])])}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
